-- A provider's at-limit policy (core `AtLimit`) is nine columns on
-- `account_routing`, not JSON: `at_limit_move`, `at_limit_wait_minutes`,
-- `at_limit_move_whole_under_k`, `at_limit_stale_after_hours`, and
-- `compaction_at_limit`, `compaction_before_move`, `compaction_file_room`,
-- `compaction_summarizer_harness`, `compaction_summarizer_model`; with
-- `at_limit_unread`.
--
-- A policy never saved has no row, as before: the provider reads the
-- default policy (core `defaultRouting`). Every row was written whole by a
-- save (routes/account-placement.ts, every field required or kept from the
-- one saved before) or filled whole by the migrations that added a field
-- (0328, 0356, 0361), so a row holds a saved policy.
--
-- A field reads as the one writer let it be written: `move` true or false;
-- `waitMinutes`, `moveWholeUnderK` and `compaction.fileRoom` whole numbers
-- from 0, `staleAfterHours` from 1; each compaction method native, summary
-- or whole; the summariser a harness CawCo runs and a model named. A key no
-- field reads (`delegateWork`, `prepareAtPct`) is ignored, as the hub's
-- reader ignored it. A `fileRoom` missing beside a `fileAtPct` of 0 is
-- placed as 0, as 0361 placed it: filing off. Each field that reads is
-- placed in its column.
--
-- A policy that does not read whole (not JSON, not an object, a field
-- missing or out of its range) is never read as the default: it is kept as
-- it was stored in `at_limit_unread`, its fields that read placed beside
-- it, and while it is set the hub acts on core `RESTRICTIVE_AT_LIMIT`: it
-- moves no session to another account by itself, compacts and summarises
-- none, files none, and names the policy in the stall words of each session
-- it holds. A save clears it. The step before this migration (db/migrate.ts
-- `at-limit-unread`) logs each such row by its provider and reason.
ALTER TABLE `account_routing` ADD `at_limit_move` integer;--> statement-breakpoint
ALTER TABLE `account_routing` ADD `at_limit_wait_minutes` integer;--> statement-breakpoint
ALTER TABLE `account_routing` ADD `at_limit_move_whole_under_k` integer;--> statement-breakpoint
ALTER TABLE `account_routing` ADD `at_limit_stale_after_hours` integer;--> statement-breakpoint
ALTER TABLE `account_routing` ADD `compaction_at_limit` text;--> statement-breakpoint
ALTER TABLE `account_routing` ADD `compaction_before_move` text;--> statement-breakpoint
ALTER TABLE `account_routing` ADD `compaction_file_room` integer;--> statement-breakpoint
ALTER TABLE `account_routing` ADD `compaction_summarizer_harness` text;--> statement-breakpoint
ALTER TABLE `account_routing` ADD `compaction_summarizer_model` text;--> statement-breakpoint
ALTER TABLE `account_routing` ADD `at_limit_unread` text;--> statement-breakpoint
UPDATE `account_routing` SET `at_limit_move` = CASE WHEN CASE WHEN CASE WHEN json_valid(`at_limit`) THEN json_type(`at_limit`) = 'object' ELSE 0 END THEN coalesce((json_type(`at_limit`, '$.move') IN ('true', 'false')), 0) ELSE 0 END THEN json_extract(`at_limit`, '$.move') END, `at_limit_wait_minutes` = CASE WHEN CASE WHEN CASE WHEN json_valid(`at_limit`) THEN json_type(`at_limit`) = 'object' ELSE 0 END THEN coalesce((json_type(`at_limit`, '$.waitMinutes') IN ('integer', 'real') AND json_extract(`at_limit`, '$.waitMinutes') >= 0 AND json_extract(`at_limit`, '$.waitMinutes') = CAST(json_extract(`at_limit`, '$.waitMinutes') AS INTEGER)), 0) ELSE 0 END THEN CAST(json_extract(`at_limit`, '$.waitMinutes') AS INTEGER) END, `at_limit_move_whole_under_k` = CASE WHEN CASE WHEN CASE WHEN json_valid(`at_limit`) THEN json_type(`at_limit`) = 'object' ELSE 0 END THEN coalesce((json_type(`at_limit`, '$.moveWholeUnderK') IN ('integer', 'real') AND json_extract(`at_limit`, '$.moveWholeUnderK') >= 0 AND json_extract(`at_limit`, '$.moveWholeUnderK') = CAST(json_extract(`at_limit`, '$.moveWholeUnderK') AS INTEGER)), 0) ELSE 0 END THEN CAST(json_extract(`at_limit`, '$.moveWholeUnderK') AS INTEGER) END, `at_limit_stale_after_hours` = CASE WHEN CASE WHEN CASE WHEN json_valid(`at_limit`) THEN json_type(`at_limit`) = 'object' ELSE 0 END THEN coalesce((json_type(`at_limit`, '$.staleAfterHours') IN ('integer', 'real') AND json_extract(`at_limit`, '$.staleAfterHours') >= 1 AND json_extract(`at_limit`, '$.staleAfterHours') = CAST(json_extract(`at_limit`, '$.staleAfterHours') AS INTEGER)), 0) ELSE 0 END THEN CAST(json_extract(`at_limit`, '$.staleAfterHours') AS INTEGER) END, `compaction_at_limit` = CASE WHEN CASE WHEN CASE WHEN json_valid(`at_limit`) THEN json_type(`at_limit`) = 'object' ELSE 0 END THEN coalesce((json_type(`at_limit`, '$.compaction.atLimit') = 'text' AND json_extract(`at_limit`, '$.compaction.atLimit') IN ('native', 'summary', 'whole')), 0) ELSE 0 END THEN json_extract(`at_limit`, '$.compaction.atLimit') END, `compaction_before_move` = CASE WHEN CASE WHEN CASE WHEN json_valid(`at_limit`) THEN json_type(`at_limit`) = 'object' ELSE 0 END THEN coalesce((json_type(`at_limit`, '$.compaction.beforeMove') = 'text' AND json_extract(`at_limit`, '$.compaction.beforeMove') IN ('native', 'summary', 'whole')), 0) ELSE 0 END THEN json_extract(`at_limit`, '$.compaction.beforeMove') END, `compaction_file_room` = CASE WHEN CASE WHEN CASE WHEN json_valid(`at_limit`) THEN json_type(`at_limit`) = 'object' ELSE 0 END THEN coalesce(((json_type(`at_limit`, '$.compaction.fileRoom') IN ('integer', 'real') AND json_extract(`at_limit`, '$.compaction.fileRoom') >= 0 AND json_extract(`at_limit`, '$.compaction.fileRoom') = CAST(json_extract(`at_limit`, '$.compaction.fileRoom') AS INTEGER)) OR (json_type(`at_limit`, '$.compaction.fileRoom') IS NULL AND json_type(`at_limit`, '$.compaction.fileAtPct') IN ('integer', 'real') AND json_extract(`at_limit`, '$.compaction.fileAtPct') = 0)), 0) ELSE 0 END THEN CASE WHEN json_type(`at_limit`, '$.compaction.fileRoom') IN ('integer', 'real') AND json_extract(`at_limit`, '$.compaction.fileRoom') >= 0 AND json_extract(`at_limit`, '$.compaction.fileRoom') = CAST(json_extract(`at_limit`, '$.compaction.fileRoom') AS INTEGER) THEN CAST(json_extract(`at_limit`, '$.compaction.fileRoom') AS INTEGER) ELSE 0 END END, `compaction_summarizer_harness` = CASE WHEN CASE WHEN CASE WHEN json_valid(`at_limit`) THEN json_type(`at_limit`) = 'object' ELSE 0 END THEN coalesce((json_type(`at_limit`, '$.compaction.summarizer.harness') = 'text' AND json_extract(`at_limit`, '$.compaction.summarizer.harness') IN ('claude', 'opencode', 'pi')), 0) ELSE 0 END THEN json_extract(`at_limit`, '$.compaction.summarizer.harness') END, `compaction_summarizer_model` = CASE WHEN CASE WHEN CASE WHEN json_valid(`at_limit`) THEN json_type(`at_limit`) = 'object' ELSE 0 END THEN coalesce((json_type(`at_limit`, '$.compaction.summarizer.model') = 'text' AND length(json_extract(`at_limit`, '$.compaction.summarizer.model')) > 0), 0) ELSE 0 END THEN json_extract(`at_limit`, '$.compaction.summarizer.model') END, `at_limit_unread` = CASE WHEN CASE WHEN CASE WHEN json_valid(`at_limit`) THEN json_type(`at_limit`) = 'object' ELSE 0 END THEN coalesce((json_type(`at_limit`, '$.move') IN ('true', 'false')), 0) AND coalesce((json_type(`at_limit`, '$.waitMinutes') IN ('integer', 'real') AND json_extract(`at_limit`, '$.waitMinutes') >= 0 AND json_extract(`at_limit`, '$.waitMinutes') = CAST(json_extract(`at_limit`, '$.waitMinutes') AS INTEGER)), 0) AND coalesce((json_type(`at_limit`, '$.moveWholeUnderK') IN ('integer', 'real') AND json_extract(`at_limit`, '$.moveWholeUnderK') >= 0 AND json_extract(`at_limit`, '$.moveWholeUnderK') = CAST(json_extract(`at_limit`, '$.moveWholeUnderK') AS INTEGER)), 0) AND coalesce((json_type(`at_limit`, '$.staleAfterHours') IN ('integer', 'real') AND json_extract(`at_limit`, '$.staleAfterHours') >= 1 AND json_extract(`at_limit`, '$.staleAfterHours') = CAST(json_extract(`at_limit`, '$.staleAfterHours') AS INTEGER)), 0) AND coalesce((json_type(`at_limit`, '$.compaction.atLimit') = 'text' AND json_extract(`at_limit`, '$.compaction.atLimit') IN ('native', 'summary', 'whole')), 0) AND coalesce((json_type(`at_limit`, '$.compaction.beforeMove') = 'text' AND json_extract(`at_limit`, '$.compaction.beforeMove') IN ('native', 'summary', 'whole')), 0) AND coalesce(((json_type(`at_limit`, '$.compaction.fileRoom') IN ('integer', 'real') AND json_extract(`at_limit`, '$.compaction.fileRoom') >= 0 AND json_extract(`at_limit`, '$.compaction.fileRoom') = CAST(json_extract(`at_limit`, '$.compaction.fileRoom') AS INTEGER)) OR (json_type(`at_limit`, '$.compaction.fileRoom') IS NULL AND json_type(`at_limit`, '$.compaction.fileAtPct') IN ('integer', 'real') AND json_extract(`at_limit`, '$.compaction.fileAtPct') = 0)), 0) AND coalesce((json_type(`at_limit`, '$.compaction.summarizer.harness') = 'text' AND json_extract(`at_limit`, '$.compaction.summar